import { readFileSync } from 'node:fs';
import t from './src/i18n/index.js';

const home = readFileSync('./src/pages/Home.jsx', 'utf8');
const keys = [...home.matchAll(/\bt\('([^']+)'\)/g)].map((m) => m[1]);
const rendered = keys.map((k) => `${k} -> ${JSON.stringify(t(k))}`);

console.log('keys referenced by Home.jsx:', rendered.join(', '));
const buttonKey = keys.at(-1);
if (t(buttonKey) !== 'Create order') {
  console.error(`FAIL: button key ${buttonKey} renders ${JSON.stringify(t(buttonKey))}`);
  process.exit(1);
}
if (/Submit/.test(home)) {
  console.error('FAIL: literal "Submit" still present in Home.jsx');
  process.exit(1);
}
console.log('PASS: homepage button renders "Create order"');

